// ----------------------------------------------------------------------

const $J = $input.first().json;
// IA · Preparar: arma la petición a Claude. Las instrucciones son fijas
// (se cachean cuando el modelo lo permite); el contexto variable va en el mensaje.
const j = $J;
const { m, cfg, eventos } = j;
const ah = ahora(cfg);

const SISTEMA = `Eres el asistente de agenda de un negocio local (clínica dental, fisio, taller, autoescuela…). Te escriben el dueño o su personal desde el móvil, deprisa, como hablarían con su recepcionista: frases a medias, coloquiales, con faltas, en castellano o gallego, o transcritas de un audio con errores. Tu tarea es entender QUÉ QUIEREN HACER con la agenda y devolverlo como una lista de acciones JSON. No conversas: el sistema responde por ti.

Entiende con generosidad. Si la intención es razonablemente clara, conviértela en acción aunque falten datos: deja a null lo que no se diga y el sistema preguntará solo eso. No exijas ningún formato.

Acciones posibles:
- "crear": dar o apuntar una cita nueva ("apunta", "ponme a", "dale cita", "reserva", "mete a", "que venga", "viene X el…", o simplemente un nombre con un día u hora). Rellena nombre, fecha, hora, tipo_cita y movil si aparecen.
- "mover": cambiar una cita que ya existe de día u hora ("pasa", "cambia", "mueve", "retrasa", "adelanta", "mejor el…"). nombre = de quién (si se dice), ref_fecha/ref_hora = cuándo era, fecha/hora = cuándo será.
- "cancelar": anular una cita ("cancela", "anula", "quita", "borra", "no viene", "se cae", "ha avisado que no puede"). nombre y/o ref_fecha/ref_hora para identificarla.
- "consultar": preguntas sobre la agenda. consulta = "dia" (qué hay un día o franja), "huecos" (qué hay libre, si cabe alguien, cuándo puedo meter a alguien), "persona" (cuándo viene alguien o qué citas tiene; pon su nombre), "semana" (cómo va la semana o los próximos días), "lista_espera" o "no_shows" (quién faltó, no vino). Usa fecha y franja ("manana" o "tarde") si se dicen.
- "ayuda": preguntas sobre el asistente o el servicio. tema = "como_funciona", "automatizaciones", "invitar" (dar acceso a alguien del equipo) u "otro".
- "saludo": saludos, gracias, "ok", "vale", "perfecto", despedidas y charla sin petición.
- "no_entendido": solo si el mensaje no tiene que ver con la agenda ni con el asistente (por ejemplo, el tiempo o el fútbol), o es imposible saber qué quiere.

Reglas:
1. Una acción por cada cosa que pidan, en orden, máximo 5.
2. Fechas AAAA-MM-DD y horas HH:MM (24 h), resueltas con la tabla de días del contexto. "Hoy", "mañana", "pasado", "el jueves", "el 14", "la semana que viene", "esta tarde", "a primera hora" (= apertura), "después de comer" (= inicio de la tarde)… Un día de la semana sin más es el de la lista «Días» (nunca el de la semana siguiente salvo que lo digan).
3. Horas ambiguas ("a las 7", "a las 5 y media", "a la 1") → la que cae dentro del horario de apertura del contexto.
4. tipo_cita: SOLO uno de los códigos de la lista de tipos del contexto. Si mencionan un tratamiento, síntoma o motivo concreto (empaste, dolor, muela, ortodoncia, contractura, ITV, aceite…), NO lo copies: elige el código genérico que mejor encaje u "OTRO". Si no se dice, null.
5. nombre: como se refieren a la persona. Si parece un error de transcripción o un apodo de alguien de la lista de habituales (Kike → Quique, Mari José → María José), usa el de la lista. No inventes apellidos. Si no se dice, null.
6. movil: solo si aparece (dígitos, puede venir con espacios o puntos). Nunca lo inventes.
7. Todo lo que no se diga va a null.

Ejemplos (fechas de ejemplo):
"Quique mañana a las 7, cancela a Marta del jueves y dime qué tengo el viernes por la tarde" → crear(nombre Quique, fecha mañana, hora 19:00); cancelar(nombre Marta, ref_fecha jueves); consultar(dia, fecha viernes, franja tarde).
"oye mete a la de las muelas, la señora Carmen, pasado a primera hora" → crear(nombre Carmen, fecha pasado mañana, hora de apertura, tipo_cita OTRO).
"apúntame una cita mañana a las 10" → crear(nombre null, fecha mañana, hora 10:00).
"la de las 10 de mañana no viene" → cancelar(nombre null, ref_fecha mañana, ref_hora 10:00).
"cuándo le toca a Luis?" → consultar(persona, nombre Luis).
"tengo algo libre el jueves por la tarde para una limpieza?" → consultar(huecos, fecha jueves, franja tarde).
"gracias!" → saludo.`;

const nul = (t) => ({ anyOf: [t, { type: 'null' }] });
const ESQUEMA = {
  type: 'object', additionalProperties: false, required: ['acciones'],
  properties: { acciones: { type: 'array', items: {
    type: 'object', additionalProperties: false,
    required: ['accion', 'nombre', 'fecha', 'hora', 'tipo_cita', 'movil', 'ref_fecha', 'ref_hora', 'consulta', 'franja', 'tema'],
    properties: {
      accion: { type: 'string', enum: ['crear', 'mover', 'cancelar', 'consultar', 'ayuda', 'saludo', 'no_entendido'] },
      nombre: nul({ type: 'string' }),
      fecha: nul({ type: 'string', format: 'date' }),
      hora: nul({ type: 'string' }),
      tipo_cita: nul({ type: 'string' }),
      movil: nul({ type: 'string' }),
      ref_fecha: nul({ type: 'string', format: 'date' }),
      ref_hora: nul({ type: 'string' }),
      consulta: nul({ type: 'string', enum: ['dia', 'huecos', 'persona', 'semana', 'lista_espera', 'no_shows'] }),
      franja: nul({ type: 'string', enum: ['manana', 'tarde'] }),
      tema: nul({ type: 'string', enum: ['como_funciona', 'automatizaciones', 'invitar', 'otro'] }),
    },
  } } },
};

// Contexto: tabla de días, horario, tipos y nombres habituales (solo nombres).
// Cada día de la semana aparece UNA vez (el próximo); la semana siguiente va aparte.
const dias = [];
const siguientes = [];
for (let i = 0; i < 7; i++) {
  const d = ah.plus({ days: i });
  const nombre = d.setLocale('es').toFormat('cccc');
  const etiqueta = i === 0 ? `hoy (${nombre})` : i === 1 ? `mañana (${nombre})` : `el ${nombre}`;
  dias.push(`${etiqueta} = ${d.toISODate()}`);
  siguientes.push(`el ${nombre} de la semana que viene = ${d.plus({ days: 7 }).toISODate()}`);
}
const DN = ['', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo'];
const horario = Object.entries(cfg.horario || {}).sort(([a], [b]) => a - b)
  .map(([d, tr]) => `${DN[d]}: ${tr.length ? tr.map(([a, b]) => `${a}-${b}`).join(' y ') : 'cerrado'}`).join('; ');
const nombres = [...new Set(habituales(cfg, eventos).map((h) => h.nombre))].slice(0, 150);

const contexto = [
  `Ahora: ${ah.setLocale('es').toFormat("cccc d 'de' LLLL 'de' yyyy, HH:mm")} (${ah.toISODate()}).`,
  `Días: ${dias.join('; ')}.`,
  `Solo si dicen «la semana que viene» o «el otro»: ${siguientes.slice(1).join('; ')}.`,
  `Horario de apertura: ${horario || 'no definido'}.`,
  `Tipos de cita (código = descripción): ${tipos(cfg).map((t) => `${t.codigo} = ${t.nombre}`).join('; ')}.`,
  `Habituales: ${nombres.length ? nombres.join(', ') : '(ninguno)'}.`,
].join('\n');

const reintento = j.ia_reintento ? `\n\nTu respuesta anterior no era válida (${j.ia_error}). Devuelve solo el JSON con el esquema indicado.` : '';
const body = {
  model: cfg.modelo_ia || 'claude-haiku-4-5',
  max_tokens: 1024,
  temperature: 0,
  system: [{ type: 'text', text: SISTEMA, cache_control: { type: 'ephemeral' } }],
  messages: [{ role: 'user', content: `<contexto>\n${contexto}\n</contexto>\n<mensaje>\n${j.texto}\n</mensaje>${reintento}` }],
  output_config: { format: { type: 'json_schema', schema: ESQUEMA } },
};
return [{ json: { ...j, ia_body: body } }];

// ---- RESPIRO · utilidades comunes (generadas por n8n/build.py: no editar en n8n) ----
// Fechas con Luxon (DateTime está disponible en los nodos Code de n8n).
const G = $('G').first().json;
const SEP = '·';
const IGNORAR = ['BLOQUEO', 'COMIDA', 'REUNION', 'FORMACION', 'VACACIONES'];
const CERRADO = 'CERRADO';
const NOVINO = 'NOVINO';
const PASO_MIN = 15;          // los huecos se buscan cada 15 min
const AVISO_MIN_MIN = 0;      // el dueño puede apuntar citas para dentro de un rato

const norm = (s) => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase().trim();
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const capital = (s) => String(s || '').replace(/(^|\s)(\p{L})/gu, (m, a, b) => a + b.toUpperCase());

const zona = (cfg) => (cfg && cfg.zona_horaria) || 'Europe/Madrid';
const ahora = (cfg) => DateTime.now().setZone(zona(cfg)).setLocale('es');
const dt = (cfg, v) => DateTime.fromISO(String(v), { zone: zona(cfg) }).setLocale('es');
const fDia = (d) => d.setLocale('es').toFormat("cccc d 'de' LLLL");
const fDiaCorto = (d) => d.setLocale('es').toFormat('ccc d');
const fHora = (d) => d.toFormat('HH:mm');
const diaRelativo = (cfg, d) => {
  const h = ahora(cfg).startOf('day');
  const x = d.setZone(zona(cfg)).startOf('day');
  const n = Math.round(x.diff(h, 'days').days);
  if (n === 0) return 'hoy';
  if (n === 1) return 'mañana';
  if (n === -1) return 'ayer';
  if (n > 1 && n < 7) return 'el ' + x.setLocale('es').toFormat('cccc d');
  return 'el ' + x.setLocale('es').toFormat("cccc d 'de' LLLL");
};

// --- Tipos genéricos de cita (nunca el tratamiento concreto) ---
const tipos = (cfg) => (Array.isArray(cfg.tipos_cita) && cfg.tipos_cita.length ? cfg.tipos_cita
  : [{ codigo: 'OTRO', nombre: 'otro', min: 30 }]);
const tipoPor = (cfg, codigo) => {
  const t = tipos(cfg);
  return t.find((x) => norm(x.codigo) === norm(codigo)) || t.find((x) => x.codigo === 'OTRO') || t[t.length - 1];
};

// --- Teléfonos ---
const normMovil = (p) => {
  if (p === null || p === undefined || p === '') return null;
  let d = String(p).replace(/[^\d+]/g, '');
  if (d.startsWith('+')) d = d.slice(1); else if (d.startsWith('00')) d = d.slice(2);
  if (d.length === 9) d = '34' + d;
  return /^\d{10,15}$/.test(d) ? d : null;
};
const movilVisible = (m) => (m ? '+' + m : 'sin móvil');

// --- Títulos del calendario: "Nombre · +34600111222 · TIPO" ---
const titulo = (cfg, nombre, movil, codigo) =>
  `${capital(nombre).trim()} ${SEP} ${movil ? '+' + movil : 'sin móvil'} ${SEP} ${tipoPor(cfg, codigo).codigo}`;

const leerTitulo = (cfg, summary) => {
  const s = String(summary || '');
  const partes = s.split(SEP).map((x) => x.trim()).filter(Boolean);
  const N = norm(s);
  const novino = N.includes(NOVINO);
  const nombre = (partes[0] || '').replace(new RegExp(NOVINO, 'i'), '').trim();
  let movil = null;
  let codigo = null;
  for (const p of partes.slice(1)) {
    const m = normMovil(p);
    if (!movil && m && /\d{6,}/.test(p.replace(/\s/g, ''))) { movil = m; continue; }
    const t = tipos(cfg).find((x) => norm(p).includes(norm(x.codigo)));
    if (!codigo && t) codigo = t.codigo;
  }
  return { nombre, movil, codigo: codigo || 'OTRO', novino };
};

const esIgnorable = (summary) => IGNORAR.some((p) => norm(summary).startsWith(p));

// Citas (eventos con hora) a partir de la respuesta de Google Calendar
const citasDe = (cfg, eventos) => (eventos || [])
  .filter((e) => e.status !== 'cancelled' && e.start && e.start.dateTime && !esIgnorable(e.summary) && !norm(e.summary).includes(CERRADO))
  .map((e) => {
    const t = leerTitulo(cfg, e.summary);
    return {
      id: e.id,
      inicio: DateTime.fromISO(e.start.dateTime).setZone(zona(cfg)),
      fin: DateTime.fromISO(e.end.dateTime).setZone(zona(cfg)),
      ...t,
    };
  })
  .sort((a, b) => a.inicio.toMillis() - b.inicio.toMillis());

// Ocupación: eventos que bloquean (cualquier evento con hora no transparente
// y los días completos marcados como CERRADO).
const ocupacion = (cfg, eventos, excluirId) => {
  const cerrados = new Set();
  const ocupado = [];
  for (const e of eventos || []) {
    if (e.status === 'cancelled' || e.transparency === 'transparent' || e.id === excluirId) continue;
    if (e.start && e.start.date) {
      if (norm(e.summary).includes(CERRADO)) {
        let d = DateTime.fromISO(e.start.date, { zone: zona(cfg) });
        const fin = DateTime.fromISO(e.end.date, { zone: zona(cfg) });
        while (d < fin) { cerrados.add(d.toISODate()); d = d.plus({ days: 1 }); }
      }
      continue;
    }
    if (!e.start || !e.start.dateTime) continue;
    ocupado.push({ s: DateTime.fromISO(e.start.dateTime).toMillis(), e: DateTime.fromISO(e.end.dateTime).toMillis() });
  }
  return { cerrados, ocupado };
};

const tramosDia = (cfg, d) => ((cfg.horario || {})[String(d.weekday)] || []);

const dentroHorario = (cfg, ini, fin) => tramosDia(cfg, ini).some(([a, b]) =>
  ini.toFormat('HH:mm') >= a && fin.toFormat('HH:mm') <= b && ini.toISODate() === fin.minus({ minutes: 1 }).toISODate());

// ¿Está libre [ini, fin)? Devuelve { libre, motivo }
const comprobarHueco = (cfg, eventos, ini, fin, excluirId) => {
  const { cerrados, ocupado } = ocupacion(cfg, eventos, excluirId);
  if (!ini.isValid) return { libre: false, motivo: 'fecha' };
  if (ini < ahora(cfg).minus({ minutes: 5 })) return { libre: false, motivo: 'pasado' };
  if (cerrados.has(ini.toISODate())) return { libre: false, motivo: 'cerrado' };
  if (!dentroHorario(cfg, ini, fin)) return { libre: false, motivo: 'horario' };
  const s = ini.toMillis();
  const e = fin.toMillis();
  if (ocupado.some((x) => x.s < e && x.e > s)) return { libre: false, motivo: 'ocupado' };
  return { libre: true, motivo: null };
};

// Huecos libres de `dur` minutos entre desde y hasta.
const huecos = (cfg, eventos, desde, hasta, dur, opts = {}) => {
  const { cerrados, ocupado } = ocupacion(cfg, eventos, opts.excluirId);
  const minimo = ahora(cfg).plus({ minutes: AVISO_MIN_MIN });
  const res = [];
  for (let dia = desde.startOf('day'); dia <= hasta; dia = dia.plus({ days: 1 })) {
    if (cerrados.has(dia.toISODate())) continue;
    for (const [a, b] of tramosDia(cfg, dia)) {
      const [ah, am] = a.split(':').map(Number);
      const [bh, bm] = b.split(':').map(Number);
      const cierre = dia.set({ hour: bh, minute: bm, second: 0, millisecond: 0 });
      for (let t = dia.set({ hour: ah, minute: am, second: 0, millisecond: 0 }); t.plus({ minutes: dur }) <= cierre; t = t.plus({ minutes: PASO_MIN })) {
        if (t < minimo || t < desde || t > hasta) continue;
        if (opts.franja === 'manana' && t.hour >= 14) continue;
        if (opts.franja === 'tarde' && t.hour < 14) continue;
        const s = t.toMillis();
        const e = t.plus({ minutes: dur }).toMillis();
        if (!ocupado.some((x) => x.s < e && x.e > s)) res.push(t);
      }
    }
  }
  return res;
};

// Agrupa huecos consecutivos en tramos "10:00–12:30" para mostrarlos.
const tramosLibres = (lista, dur) => {
  const out = [];
  for (const t of lista) {
    const ult = out[out.length - 1];
    if (ult && ult.dia === t.toISODate() && t <= ult.fin) ult.fin = t.plus({ minutes: dur });
    else out.push({ dia: t.toISODate(), ini: t, fin: t.plus({ minutes: dur }) });
  }
  return out;
};

// Siguientes huecos cerca de una hora pedida (mismo día primero, luego días siguientes)
const alternativas = (cfg, eventos, ini, dur, n = 3, excluirId) => {
  const mismoDia = huecos(cfg, eventos, ini.startOf('day'), ini.endOf('day'), dur, { excluirId })
    .sort((a, b) => Math.abs(a.diff(ini).toMillis()) - Math.abs(b.diff(ini).toMillis()));
  const out = [];
  for (const t of mismoDia) {
    if (out.length >= n) break;
    if (out.some((o) => Math.abs(o.diff(t, 'minutes').minutes) < dur)) continue;
    out.push(t);
  }
  if (out.length < n) {
    const otros = huecos(cfg, eventos, ini.plus({ days: 1 }).startOf('day'), ini.plus({ days: 14 }).endOf('day'), dur, { excluirId });
    for (const t of otros) {
      if (out.length >= n) break;
      if (out.some((o) => o.toISODate() === t.toISODate())) continue;   // uno por día
      out.push(t);
    }
  }
  return out.sort((a, b) => a.toMillis() - b.toMillis());
};

// Busca citas por nombre (tolerante a tildes y a nombre parcial).
const coincideNombre = (nombreCita, buscado) => {
  if (!buscado) return false;
  const a = norm(nombreCita);
  const b = norm(buscado);
  if (!a || !b) return false;
  if (a === b) return true;
  const pa = a.split(/\s+/);
  const pb = b.split(/\s+/);
  return pb.every((x) => pa.some((y) => y === x || (x.length >= 4 && y.startsWith(x))));
};

// Pacientes habituales (solo nombre y móvil) sacados del calendario.
const habituales = (cfg, eventos) => {
  const m = new Map();
  for (const c of citasDe(cfg, eventos)) {
    if (!c.nombre) continue;
    const k = norm(c.nombre) + '|' + (c.movil || '');
    const prev = m.get(k);
    if (!prev || prev.ultima < c.inicio) m.set(k, { nombre: c.nombre, movil: c.movil, ultima: c.inicio });
  }
  return [...m.values()].sort((a, b) => b.ultima.toMillis() - a.ultima.toMillis());
};

// Mensaje de Telegram (sendMessage / editMessageText / answerCallbackQuery / sendPhoto)
const tgTexto = (chat_id, text, botones, extra = {}) => ({
  method: 'sendMessage',
  body: {
    chat_id, text, parse_mode: 'HTML', disable_web_page_preview: true,
    ...(botones && botones.length ? { reply_markup: { inline_keyboard: botones } } : {}),
    ...extra,
  },
});
const tgEditar = (chat_id, message_id, text, botones) => ({
  method: 'editMessageText',
  body: {
    chat_id, message_id, text, parse_mode: 'HTML', disable_web_page_preview: true,
    reply_markup: { inline_keyboard: botones || [] },
  },
});
const tgAviso = (callback_query_id, text) => ({ method: 'answerCallbackQuery', body: { callback_query_id, ...(text ? { text } : {}) } });
const tgFoto = (chat_id, foto, caption, botones) => ({
  method: 'sendPhoto',
  body: {
    chat_id, photo: foto, caption, parse_mode: 'HTML',
    ...(botones && botones.length ? { reply_markup: { inline_keyboard: botones } } : {}),
  },
});
// La sección va en ?s= (Telegram usa el # de la URL para pasar initData a la Mini App)
const botonApp = (texto, seccion = '') => [{ text: texto, web_app: { url: G.miniapp_url + (seccion ? '?s=' + seccion : '') } }];
const robot = (expresion) => `${G.miniapp_url}robot/${expresion}.png`;

// Elemento de log para respiro.log_eventos (SIN datos personales)
const log = (cfg, automatizacion, tipo, resultado, origen, metadatos = {}) => ({
  cliente_id: cfg.cliente_id, automatizacion, tipo, resultado, origen, metadatos,
});

// --- Estado de una cita para mostrar (sin datos de salud) ---
// confirmada: la marca el flujo de confirmaciones con extendedProperties
// o con la palabra CONFIRMADA en el título; NOVINO = no vino.
const estadoCita = (e, c) => {
  if (c.novino) return 'no_vino';
  const priv = (e.extendedProperties && e.extendedProperties.private) || {};
  if (priv.respiro_estado === 'confirmada' || norm(e.summary).includes('CONFIRMADA')) return 'confirmada';
  return 'pendiente';
};
const ICONO_ESTADO = { confirmada: '✅', pendiente: '🕓', no_vino: '❌' };
const duracionMinima = (cfg) => Math.min(...tipos(cfg).map((t) => Number(t.min) || 30));

const lineaCita = (cfg, c) => `${fHora(c.inicio)} · ${esc(c.nombre)} · ${esc(tipoPor(cfg, c.codigo).nombre)}`;

// Texto de una consulta: dia | huecos | lista_espera | no_shows
const textoConsulta = (cfg, eventos, q, espera) => {
  const hoy = ahora(cfg).startOf('day');
  if (q.consulta === 'lista_espera') {
    const l = espera || [];
    if (!l.length) return '📋 <b>Lista de espera</b>\nAhora mismo no hay nadie esperando.';
    return '📋 <b>Lista de espera</b> (' + l.length + ')\n' + l.slice(0, 15).map((x) => `• ${esc(x.nombre)} · ${esc(tipoPor(cfg, x.tipo).nombre)}${x.preferencia ? ' · ' + esc(x.preferencia) : ''}`).join('\n');
  }
  if (q.consulta === 'no_shows') {
    const desde = hoy.minus({ days: 30 });
    const l = citasDe(cfg, eventos).filter((c) => c.novino && c.inicio >= desde && c.inicio <= ahora(cfg));
    if (!l.length) return '🙌 <b>No-shows</b>\nNadie ha faltado en los últimos 30 días.';
    return `❌ <b>No-shows</b> (últimos 30 días): ${l.length}\n` + l.slice(-10).map((c) => `• ${fDiaCorto(c.inicio)} ${fHora(c.inicio)} · ${esc(c.nombre)}`).join('\n');
  }
  if (q.consulta === 'persona') {
    if (!q.nombre) return '🔎 ¿De quién quieres saber las citas?';
    const l = citasDe(cfg, eventos).filter((c) => coincideNombre(c.nombre, q.nombre) && c.inicio >= hoy);
    if (!l.length) return `🔎 No veo citas próximas de <b>${esc(q.nombre)}</b>.`;
    return `🔎 <b>Citas de ${esc(q.nombre)}</b>\n` + l.slice(0, 6).map((c) => `• ${capital(diaRelativo(cfg, c.inicio).replace(/^el /, ''))} a las ${fHora(c.inicio)} · ${esc(c.nombre)} · ${esc(tipoPor(cfg, c.codigo).nombre)}`).join('\n');
  }
  if (q.consulta === 'semana') {
    const lineas = [];
    for (let i = 0; i < 7; i++) {
      const d = hoy.plus({ days: i });
      const n = citasDe(cfg, eventos).filter((c) => c.inicio.toISODate() === d.toISODate()).length;
      if (!tramosDia(cfg, d).length && !n) continue;
      lineas.push(`• ${capital(diaRelativo(cfg, d).replace(/^el /, ''))}: ${n} cita${n === 1 ? '' : 's'}`);
    }
    return '📅 <b>Próximos días</b>\n' + (lineas.length ? lineas.join('\n') : 'Sin días de apertura.');
  }
  const dur = duracionMinima(cfg);
  if (q.consulta === 'huecos') {
    let desde = q.fecha ? dt(cfg, q.fecha).startOf('day') : ahora(cfg);
    let dias = q.fecha ? 1 : 3;
    const out = [];
    for (let d = desde, n = 0; n < dias && d < hoy.plus({ days: 21 }); d = d.plus({ days: 1 }).startOf('day')) {
      if (!tramosDia(cfg, d).length) continue;
      n++;
      const l = tramosLibres(huecos(cfg, eventos, d, d.endOf('day'), dur, { franja: q.franja }), dur);
      out.push(`<b>${capital(diaRelativo(cfg, d).replace(/^el /, ''))}</b>: ` + (l.length ? l.map((t) => `${fHora(t.ini)}–${fHora(t.fin)}`).join(', ') : 'completo'));
    }
    if (!out.length) return '🗓 No abres en esos días.';
    return `🟢 <b>Huecos libres</b>${q.franja ? ' (por la ' + (q.franja === 'manana' ? 'mañana' : 'tarde') + ')' : ''}\n` + out.join('\n');
  }
  // dia
  const d = q.fecha ? dt(cfg, q.fecha).startOf('day') : hoy;
  let l = citasDe(cfg, eventos).filter((c) => c.inicio.toISODate() === d.toISODate());
  if (q.franja === 'manana') l = l.filter((c) => c.inicio.hour < 14);
  if (q.franja === 'tarde') l = l.filter((c) => c.inicio.hour >= 14);
  const porId = new Map((eventos || []).map((e) => [e.id, e]));
  const cab = `🗓 <b>${capital(diaRelativo(cfg, d))}</b> · ${d.toFormat('d/LL')}${q.franja ? (q.franja === 'manana' ? ' · mañana' : ' · tarde') : ''}`;
  if (!tramosDia(cfg, d).length && !l.length) return cab + '\nEse día no abres.';
  const lineas = l.map((c) => `${ICONO_ESTADO[estadoCita(porId.get(c.id) || {}, c)]} ${lineaCita(cfg, c)}`);
  const libres = tramosLibres(huecos(cfg, eventos, d, d.endOf('day'), dur, { franja: q.franja }), dur);
  return cab + '\n' + (lineas.length ? lineas.join('\n') : 'No tienes citas.') +
    (libres.length ? '\n\n🟢 Libre: ' + libres.slice(0, 6).map((t) => `${fHora(t.ini)}–${fHora(t.fin)}`).join(', ') : (tramosDia(cfg, d).length ? '\n\nSin huecos libres.' : ''));
};

const TEXTO_AYUDA = {
  general: '🤖 <b>Soy tu asistente de agenda.</b>\n\nEscríbeme o mándame un audio como se lo dirías a tu recepcionista:\n• «Quique mañana a las 7, limpieza»\n• «Mueve a Ana del jueves a las 10»\n• «Cancela a Marta del viernes»\n• «¿Qué tengo el viernes por la tarde?»\n\nAntes de tocar tu calendario te enseño un resumen y solo lo hago si pulsas <b>Sí</b>.\n\nAtajos: /hoy /manana /huecos /informe /invitar /ayuda',
  como_funciona: '🤖 Entiendo lo que me escribes o me dices, te enseño un resumen y, cuando pulsas <b>Sí</b>, lo apunto en tu Google Calendar. Desde ahí siguen funcionando tus recordatorios y confirmaciones como siempre.\n\nNo guardo audios ni el motivo de la consulta: solo nombre, móvil y un tipo general de cita (revisión, limpieza…).',
  automatizaciones: '⚙️ Tus automatizaciones y lo que han hecho este mes están en <b>Mis automatizaciones</b>, dentro de la app (botón de abajo o /informe).',
  invitar: '👥 Para dar acceso a alguien de tu equipo escribe /invitar. Te daré un enlace de un solo uso que caduca en 48 horas; se lo pasas y listo.',
};
// ----------------------------------------------------------------------

const $J = $input.first().json;
// IA · Validar: comprueba el JSON contra el catálogo cerrado. Un reintento;
// si sigue sin valer → no_entendido. Nunca se ejecuta nada sin validar.
const prev = $('IA · Preparar').first().json;
const r = $J;
const { ia_body, ...ctx } = prev;
const ACC = ['crear', 'mover', 'cancelar', 'consultar', 'ayuda', 'saludo', 'no_entendido'];
const FECHA = /^\d{4}-\d{2}-\d{2}$/;
const HORA = /^([01]?\d|2[0-3]):[0-5]\d$/;
const u = r.usage || {};
const consumo = {
  modelo: ia_body.model,
  entrada: (prev.consumo?.entrada || 0) + (u.input_tokens || 0),
  salida: (prev.consumo?.salida || 0) + (u.output_tokens || 0),
  cache_lect: (prev.consumo?.cache_lect || 0) + (u.cache_read_input_tokens || 0),
  cache_escr: (prev.consumo?.cache_escr || 0) + (u.cache_creation_input_tokens || 0),
};

let error = null;
let errorApi = null;
let acciones = null;
if (r.error || !Array.isArray(r.content)) {
  const e = r.error || {};
  errorApi = String(e.message || e.type || JSON.stringify(e)).slice(0, 300);
  error = 'api';
} else if (r.stop_reason === 'refusal') {
  error = 'rechazo';
} else {
  try {
    const txt = r.content.filter((b) => b.type === 'text').map((b) => b.text).join('');
    const o = JSON.parse(txt);
    if (!o || !Array.isArray(o.acciones)) throw new Error('sin lista de acciones');
    // Tolerante: una acción rara no tira el mensaje entero; lo que falte lo pregunta el Plan.
    const s = (v, max = 80) => (typeof v === 'string' && v.trim() ? v.trim().slice(0, max) : null);
    const hora = (v) => {
      const m = String(v || '').match(/^(\d{1,2})(?:[:.h](\d{2}))?/);
      if (!m || Number(m[1]) > 23 || Number(m[2] || 0) > 59) return null;
      return `${m[1].padStart(2, '0')}:${(m[2] || '00')}`;
    };
    acciones = o.acciones.filter((a) => a && ACC.includes(a.accion)).slice(0, 5).map((a) => {
      const out = {
        accion: a.accion,
        nombre: s(a.nombre),
        fecha: FECHA.test(a.fecha || '') ? a.fecha : null,
        hora: hora(a.hora),
        tipo_cita: s(a.tipo_cita, 20),
        movil: s(a.movil, 20),
        ref_fecha: FECHA.test(a.ref_fecha || '') ? a.ref_fecha : null,
        ref_hora: hora(a.ref_hora),
        consulta: ['dia', 'huecos', 'persona', 'semana', 'lista_espera', 'no_shows'].includes(a.consulta) ? a.consulta : null,
        franja: ['manana', 'tarde'].includes(a.franja) ? a.franja : null,
        tema: ['como_funciona', 'automatizaciones', 'invitar', 'otro'].includes(a.tema) ? a.tema : null,
      };
      if (out.accion === 'consultar' && !out.consulta) out.consulta = out.nombre ? 'persona' : 'dia';
      return out;
    });
    if (!acciones.length) acciones = [{ accion: 'no_entendido' }];
    if (o.acciones.filter((a) => a && ACC.includes(a.accion)).length > 5) acciones.push({ accion: 'demasiadas' });
  } catch (e) {
    error = 'json: ' + String(e.message).slice(0, 120);
  }
}

const reintentar = !!error && error !== 'api' && !prev.ia_reintento;
if (reintentar) return [{ json: { ...ctx, consumo, ia_reintento: true, ia_error: error, reintentar: true } }];
if (error) acciones = [{ accion: errorApi ? 'error_ia' : 'no_entendido' }];
return [{ json: { ...ctx, consumo, acciones, ia_error: error, ia_error_api: errorApi, reintentar: false, siguiente: 'plan' } }];

// ---- RESPIRO · utilidades comunes (generadas por n8n/build.py: no editar en n8n) ----
// Fechas con Luxon (DateTime está disponible en los nodos Code de n8n).
const G = $('G').first().json;
const SEP = '·';
const IGNORAR = ['BLOQUEO', 'COMIDA', 'REUNION', 'FORMACION', 'VACACIONES'];
const CERRADO = 'CERRADO';
const NOVINO = 'NOVINO';
const PASO_MIN = 15;          // los huecos se buscan cada 15 min
const AVISO_MIN_MIN = 0;      // el dueño puede apuntar citas para dentro de un rato

const norm = (s) => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase().trim();
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const capital = (s) => String(s || '').replace(/(^|\s)(\p{L})/gu, (m, a, b) => a + b.toUpperCase());

const zona = (cfg) => (cfg && cfg.zona_horaria) || 'Europe/Madrid';
const ahora = (cfg) => DateTime.now().setZone(zona(cfg)).setLocale('es');
const dt = (cfg, v) => DateTime.fromISO(String(v), { zone: zona(cfg) }).setLocale('es');
const fDia = (d) => d.setLocale('es').toFormat("cccc d 'de' LLLL");
const fDiaCorto = (d) => d.setLocale('es').toFormat('ccc d');
const fHora = (d) => d.toFormat('HH:mm');
const diaRelativo = (cfg, d) => {
  const h = ahora(cfg).startOf('day');
  const x = d.setZone(zona(cfg)).startOf('day');
  const n = Math.round(x.diff(h, 'days').days);
  if (n === 0) return 'hoy';
  if (n === 1) return 'mañana';
  if (n === -1) return 'ayer';
  if (n > 1 && n < 7) return 'el ' + x.setLocale('es').toFormat('cccc d');
  return 'el ' + x.setLocale('es').toFormat("cccc d 'de' LLLL");
};

// --- Tipos genéricos de cita (nunca el tratamiento concreto) ---
const tipos = (cfg) => (Array.isArray(cfg.tipos_cita) && cfg.tipos_cita.length ? cfg.tipos_cita
  : [{ codigo: 'OTRO', nombre: 'otro', min: 30 }]);
const tipoPor = (cfg, codigo) => {
  const t = tipos(cfg);
  return t.find((x) => norm(x.codigo) === norm(codigo)) || t.find((x) => x.codigo === 'OTRO') || t[t.length - 1];
};

// --- Teléfonos ---
const normMovil = (p) => {
  if (p === null || p === undefined || p === '') return null;
  let d = String(p).replace(/[^\d+]/g, '');
  if (d.startsWith('+')) d = d.slice(1); else if (d.startsWith('00')) d = d.slice(2);
  if (d.length === 9) d = '34' + d;
  return /^\d{10,15}$/.test(d) ? d : null;
};
const movilVisible = (m) => (m ? '+' + m : 'sin móvil');

// --- Títulos del calendario: "Nombre · +34600111222 · TIPO" ---
const titulo = (cfg, nombre, movil, codigo) =>
  `${capital(nombre).trim()} ${SEP} ${movil ? '+' + movil : 'sin móvil'} ${SEP} ${tipoPor(cfg, codigo).codigo}`;

const leerTitulo = (cfg, summary) => {
  const s = String(summary || '');
  const partes = s.split(SEP).map((x) => x.trim()).filter(Boolean);
  const N = norm(s);
  const novino = N.includes(NOVINO);
  const nombre = (partes[0] || '').replace(new RegExp(NOVINO, 'i'), '').trim();
  let movil = null;
  let codigo = null;
  for (const p of partes.slice(1)) {
    const m = normMovil(p);
    if (!movil && m && /\d{6,}/.test(p.replace(/\s/g, ''))) { movil = m; continue; }
    const t = tipos(cfg).find((x) => norm(p).includes(norm(x.codigo)));
    if (!codigo && t) codigo = t.codigo;
  }
  return { nombre, movil, codigo: codigo || 'OTRO', novino };
};

const esIgnorable = (summary) => IGNORAR.some((p) => norm(summary).startsWith(p));

// Citas (eventos con hora) a partir de la respuesta de Google Calendar
const citasDe = (cfg, eventos) => (eventos || [])
  .filter((e) => e.status !== 'cancelled' && e.start && e.start.dateTime && !esIgnorable(e.summary) && !norm(e.summary).includes(CERRADO))
  .map((e) => {
    const t = leerTitulo(cfg, e.summary);
    return {
      id: e.id,
      inicio: DateTime.fromISO(e.start.dateTime).setZone(zona(cfg)),
      fin: DateTime.fromISO(e.end.dateTime).setZone(zona(cfg)),
      ...t,
    };
  })
  .sort((a, b) => a.inicio.toMillis() - b.inicio.toMillis());

// Ocupación: eventos que bloquean (cualquier evento con hora no transparente
// y los días completos marcados como CERRADO).
const ocupacion = (cfg, eventos, excluirId) => {
  const cerrados = new Set();
  const ocupado = [];
  for (const e of eventos || []) {
    if (e.status === 'cancelled' || e.transparency === 'transparent' || e.id === excluirId) continue;
    if (e.start && e.start.date) {
      if (norm(e.summary).includes(CERRADO)) {
        let d = DateTime.fromISO(e.start.date, { zone: zona(cfg) });
        const fin = DateTime.fromISO(e.end.date, { zone: zona(cfg) });
        while (d < fin) { cerrados.add(d.toISODate()); d = d.plus({ days: 1 }); }
      }
      continue;
    }
    if (!e.start || !e.start.dateTime) continue;
    ocupado.push({ s: DateTime.fromISO(e.start.dateTime).toMillis(), e: DateTime.fromISO(e.end.dateTime).toMillis() });
  }
  return { cerrados, ocupado };
};

const tramosDia = (cfg, d) => ((cfg.horario || {})[String(d.weekday)] || []);

const dentroHorario = (cfg, ini, fin) => tramosDia(cfg, ini).some(([a, b]) =>
  ini.toFormat('HH:mm') >= a && fin.toFormat('HH:mm') <= b && ini.toISODate() === fin.minus({ minutes: 1 }).toISODate());

// ¿Está libre [ini, fin)? Devuelve { libre, motivo }
const comprobarHueco = (cfg, eventos, ini, fin, excluirId) => {
  const { cerrados, ocupado } = ocupacion(cfg, eventos, excluirId);
  if (!ini.isValid) return { libre: false, motivo: 'fecha' };
  if (ini < ahora(cfg).minus({ minutes: 5 })) return { libre: false, motivo: 'pasado' };
  if (cerrados.has(ini.toISODate())) return { libre: false, motivo: 'cerrado' };
  if (!dentroHorario(cfg, ini, fin)) return { libre: false, motivo: 'horario' };
  const s = ini.toMillis();
  const e = fin.toMillis();
  if (ocupado.some((x) => x.s < e && x.e > s)) return { libre: false, motivo: 'ocupado' };
  return { libre: true, motivo: null };
};

// Huecos libres de `dur` minutos entre desde y hasta.
const huecos = (cfg, eventos, desde, hasta, dur, opts = {}) => {
  const { cerrados, ocupado } = ocupacion(cfg, eventos, opts.excluirId);
  const minimo = ahora(cfg).plus({ minutes: AVISO_MIN_MIN });
  const res = [];
  for (let dia = desde.startOf('day'); dia <= hasta; dia = dia.plus({ days: 1 })) {
    if (cerrados.has(dia.toISODate())) continue;
    for (const [a, b] of tramosDia(cfg, dia)) {
      const [ah, am] = a.split(':').map(Number);
      const [bh, bm] = b.split(':').map(Number);
      const cierre = dia.set({ hour: bh, minute: bm, second: 0, millisecond: 0 });
      for (let t = dia.set({ hour: ah, minute: am, second: 0, millisecond: 0 }); t.plus({ minutes: dur }) <= cierre; t = t.plus({ minutes: PASO_MIN })) {
        if (t < minimo || t < desde || t > hasta) continue;
        if (opts.franja === 'manana' && t.hour >= 14) continue;
        if (opts.franja === 'tarde' && t.hour < 14) continue;
        const s = t.toMillis();
        const e = t.plus({ minutes: dur }).toMillis();
        if (!ocupado.some((x) => x.s < e && x.e > s)) res.push(t);
      }
    }
  }
  return res;
};

// Agrupa huecos consecutivos en tramos "10:00–12:30" para mostrarlos.
const tramosLibres = (lista, dur) => {
  const out = [];
  for (const t of lista) {
    const ult = out[out.length - 1];
    if (ult && ult.dia === t.toISODate() && t <= ult.fin) ult.fin = t.plus({ minutes: dur });
    else out.push({ dia: t.toISODate(), ini: t, fin: t.plus({ minutes: dur }) });
  }
  return out;
};

// Siguientes huecos cerca de una hora pedida (mismo día primero, luego días siguientes)
const alternativas = (cfg, eventos, ini, dur, n = 3, excluirId) => {
  const mismoDia = huecos(cfg, eventos, ini.startOf('day'), ini.endOf('day'), dur, { excluirId })
    .sort((a, b) => Math.abs(a.diff(ini).toMillis()) - Math.abs(b.diff(ini).toMillis()));
  const out = [];
  for (const t of mismoDia) {
    if (out.length >= n) break;
    if (out.some((o) => Math.abs(o.diff(t, 'minutes').minutes) < dur)) continue;
    out.push(t);
  }
  if (out.length < n) {
    const otros = huecos(cfg, eventos, ini.plus({ days: 1 }).startOf('day'), ini.plus({ days: 14 }).endOf('day'), dur, { excluirId });
    for (const t of otros) {
      if (out.length >= n) break;
      if (out.some((o) => o.toISODate() === t.toISODate())) continue;   // uno por día
      out.push(t);
    }
  }
  return out.sort((a, b) => a.toMillis() - b.toMillis());
};

// Busca citas por nombre (tolerante a tildes y a nombre parcial).
const coincideNombre = (nombreCita, buscado) => {
  if (!buscado) return false;
  const a = norm(nombreCita);
  const b = norm(buscado);
  if (!a || !b) return false;
  if (a === b) return true;
  const pa = a.split(/\s+/);
  const pb = b.split(/\s+/);
  return pb.every((x) => pa.some((y) => y === x || (x.length >= 4 && y.startsWith(x))));
};

// Pacientes habituales (solo nombre y móvil) sacados del calendario.
const habituales = (cfg, eventos) => {
  const m = new Map();
  for (const c of citasDe(cfg, eventos)) {
    if (!c.nombre) continue;
    const k = norm(c.nombre) + '|' + (c.movil || '');
    const prev = m.get(k);
    if (!prev || prev.ultima < c.inicio) m.set(k, { nombre: c.nombre, movil: c.movil, ultima: c.inicio });
  }
  return [...m.values()].sort((a, b) => b.ultima.toMillis() - a.ultima.toMillis());
};

// Mensaje de Telegram (sendMessage / editMessageText / answerCallbackQuery / sendPhoto)
const tgTexto = (chat_id, text, botones, extra = {}) => ({
  method: 'sendMessage',
  body: {
    chat_id, text, parse_mode: 'HTML', disable_web_page_preview: true,
    ...(botones && botones.length ? { reply_markup: { inline_keyboard: botones } } : {}),
    ...extra,
  },
});
const tgEditar = (chat_id, message_id, text, botones) => ({
  method: 'editMessageText',
  body: {
    chat_id, message_id, text, parse_mode: 'HTML', disable_web_page_preview: true,
    reply_markup: { inline_keyboard: botones || [] },
  },
});
const tgAviso = (callback_query_id, text) => ({ method: 'answerCallbackQuery', body: { callback_query_id, ...(text ? { text } : {}) } });
const tgFoto = (chat_id, foto, caption, botones) => ({
  method: 'sendPhoto',
  body: {
    chat_id, photo: foto, caption, parse_mode: 'HTML',
    ...(botones && botones.length ? { reply_markup: { inline_keyboard: botones } } : {}),
  },
});
// La sección va en ?s= (Telegram usa el # de la URL para pasar initData a la Mini App)
const botonApp = (texto, seccion = '') => [{ text: texto, web_app: { url: G.miniapp_url + (seccion ? '?s=' + seccion : '') } }];
const robot = (expresion) => `${G.miniapp_url}robot/${expresion}.png`;

// Elemento de log para respiro.log_eventos (SIN datos personales)
const log = (cfg, automatizacion, tipo, resultado, origen, metadatos = {}) => ({
  cliente_id: cfg.cliente_id, automatizacion, tipo, resultado, origen, metadatos,
});

// --- Estado de una cita para mostrar (sin datos de salud) ---
// confirmada: la marca el flujo de confirmaciones con extendedProperties
// o con la palabra CONFIRMADA en el título; NOVINO = no vino.
const estadoCita = (e, c) => {
  if (c.novino) return 'no_vino';
  const priv = (e.extendedProperties && e.extendedProperties.private) || {};
  if (priv.respiro_estado === 'confirmada' || norm(e.summary).includes('CONFIRMADA')) return 'confirmada';
  return 'pendiente';
};
const ICONO_ESTADO = { confirmada: '✅', pendiente: '🕓', no_vino: '❌' };
const duracionMinima = (cfg) => Math.min(...tipos(cfg).map((t) => Number(t.min) || 30));

const lineaCita = (cfg, c) => `${fHora(c.inicio)} · ${esc(c.nombre)} · ${esc(tipoPor(cfg, c.codigo).nombre)}`;

// Texto de una consulta: dia | huecos | lista_espera | no_shows
const textoConsulta = (cfg, eventos, q, espera) => {
  const hoy = ahora(cfg).startOf('day');
  if (q.consulta === 'lista_espera') {
    const l = espera || [];
    if (!l.length) return '📋 <b>Lista de espera</b>\nAhora mismo no hay nadie esperando.';
    return '📋 <b>Lista de espera</b> (' + l.length + ')\n' + l.slice(0, 15).map((x) => `• ${esc(x.nombre)} · ${esc(tipoPor(cfg, x.tipo).nombre)}${x.preferencia ? ' · ' + esc(x.preferencia) : ''}`).join('\n');
  }
  if (q.consulta === 'no_shows') {
    const desde = hoy.minus({ days: 30 });
    const l = citasDe(cfg, eventos).filter((c) => c.novino && c.inicio >= desde && c.inicio <= ahora(cfg));
    if (!l.length) return '🙌 <b>No-shows</b>\nNadie ha faltado en los últimos 30 días.';
    return `❌ <b>No-shows</b> (últimos 30 días): ${l.length}\n` + l.slice(-10).map((c) => `• ${fDiaCorto(c.inicio)} ${fHora(c.inicio)} · ${esc(c.nombre)}`).join('\n');
  }
  if (q.consulta === 'persona') {
    if (!q.nombre) return '🔎 ¿De quién quieres saber las citas?';
    const l = citasDe(cfg, eventos).filter((c) => coincideNombre(c.nombre, q.nombre) && c.inicio >= hoy);
    if (!l.length) return `🔎 No veo citas próximas de <b>${esc(q.nombre)}</b>.`;
    return `🔎 <b>Citas de ${esc(q.nombre)}</b>\n` + l.slice(0, 6).map((c) => `• ${capital(diaRelativo(cfg, c.inicio).replace(/^el /, ''))} a las ${fHora(c.inicio)} · ${esc(c.nombre)} · ${esc(tipoPor(cfg, c.codigo).nombre)}`).join('\n');
  }
  if (q.consulta === 'semana') {
    const lineas = [];
    for (let i = 0; i < 7; i++) {
      const d = hoy.plus({ days: i });
      const n = citasDe(cfg, eventos).filter((c) => c.inicio.toISODate() === d.toISODate()).length;
      if (!tramosDia(cfg, d).length && !n) continue;
      lineas.push(`• ${capital(diaRelativo(cfg, d).replace(/^el /, ''))}: ${n} cita${n === 1 ? '' : 's'}`);
    }
    return '📅 <b>Próximos días</b>\n' + (lineas.length ? lineas.join('\n') : 'Sin días de apertura.');
  }
  const dur = duracionMinima(cfg);
  if (q.consulta === 'huecos') {
    let desde = q.fecha ? dt(cfg, q.fecha).startOf('day') : ahora(cfg);
    let dias = q.fecha ? 1 : 3;
    const out = [];
    for (let d = desde, n = 0; n < dias && d < hoy.plus({ days: 21 }); d = d.plus({ days: 1 }).startOf('day')) {
      if (!tramosDia(cfg, d).length) continue;
      n++;
      const l = tramosLibres(huecos(cfg, eventos, d, d.endOf('day'), dur, { franja: q.franja }), dur);
      out.push(`<b>${capital(diaRelativo(cfg, d).replace(/^el /, ''))}</b>: ` + (l.length ? l.map((t) => `${fHora(t.ini)}–${fHora(t.fin)}`).join(', ') : 'completo'));
    }
    if (!out.length) return '🗓 No abres en esos días.';
    return `🟢 <b>Huecos libres</b>${q.franja ? ' (por la ' + (q.franja === 'manana' ? 'mañana' : 'tarde') + ')' : ''}\n` + out.join('\n');
  }
  // dia
  const d = q.fecha ? dt(cfg, q.fecha).startOf('day') : hoy;
  let l = citasDe(cfg, eventos).filter((c) => c.inicio.toISODate() === d.toISODate());
  if (q.franja === 'manana') l = l.filter((c) => c.inicio.hour < 14);
  if (q.franja === 'tarde') l = l.filter((c) => c.inicio.hour >= 14);
  const porId = new Map((eventos || []).map((e) => [e.id, e]));
  const cab = `🗓 <b>${capital(diaRelativo(cfg, d))}</b> · ${d.toFormat('d/LL')}${q.franja ? (q.franja === 'manana' ? ' · mañana' : ' · tarde') : ''}`;
  if (!tramosDia(cfg, d).length && !l.length) return cab + '\nEse día no abres.';
  const lineas = l.map((c) => `${ICONO_ESTADO[estadoCita(porId.get(c.id) || {}, c)]} ${lineaCita(cfg, c)}`);
  const libres = tramosLibres(huecos(cfg, eventos, d, d.endOf('day'), dur, { franja: q.franja }), dur);
  return cab + '\n' + (lineas.length ? lineas.join('\n') : 'No tienes citas.') +
    (libres.length ? '\n\n🟢 Libre: ' + libres.slice(0, 6).map((t) => `${fHora(t.ini)}–${fHora(t.fin)}`).join(', ') : (tramosDia(cfg, d).length ? '\n\nSin huecos libres.' : ''));
};

const TEXTO_AYUDA = {
  general: '🤖 <b>Soy tu asistente de agenda.</b>\n\nEscríbeme o mándame un audio como se lo dirías a tu recepcionista:\n• «Quique mañana a las 7, limpieza»\n• «Mueve a Ana del jueves a las 10»\n• «Cancela a Marta del viernes»\n• «¿Qué tengo el viernes por la tarde?»\n\nAntes de tocar tu calendario te enseño un resumen y solo lo hago si pulsas <b>Sí</b>.\n\nAtajos: /hoy /manana /huecos /informe /invitar /ayuda',
  como_funciona: '🤖 Entiendo lo que me escribes o me dices, te enseño un resumen y, cuando pulsas <b>Sí</b>, lo apunto en tu Google Calendar. Desde ahí siguen funcionando tus recordatorios y confirmaciones como siempre.\n\nNo guardo audios ni el motivo de la consulta: solo nombre, móvil y un tipo general de cita (revisión, limpieza…).',
  automatizaciones: '⚙️ Tus automatizaciones y lo que han hecho este mes están en <b>Mis automatizaciones</b>, dentro de la app (botón de abajo o /informe).',
  invitar: '👥 Para dar acceso a alguien de tu equipo escribe /invitar. Te daré un enlace de un solo uso que caduca en 48 horas; se lo pasas y listo.',
};
// ----------------------------------------------------------------------

const $J = $input.first().json;
// Plan · convierte acciones en cambios concretos y comprobados. Nada se
// escribe aquí: el resultado se guarda como pendiente hasta que se pulse "Sí".
// Entradas posibles:
//  - acciones de la IA (j.acciones)
//  - respuesta escrita a una pregunta (j.pendiente + j.respuesta)
//  - botón de elección (j.pendiente + j.eleccion)
const j = $J;
const { m, cfg } = j;
const eventos = j.eventos || [];
const ESCRITURA = ['crear', 'mover', 'cancelar'];
const logs = [];
const info = [];
const admin = [];
const origen = m.tipo === 'callback' ? `tg:cb:${m.cb_id}` : `tg:m:${m.upd}`;

// --- 1. Lista de acciones de escritura a resolver ---
let acciones = [];
if (j.pendiente) {
  acciones = (j.pendiente.acciones || []).map((a) => ({ ...a }));
  const pq = j.pendiente.pregunta;
  if (j.respuesta !== undefined && pq) {
    const a = acciones[pq.i];
    if (a && pq.tipo === 'nombre') {
      a.nombre = capital(String(j.respuesta).trim().replace(/^(es |para |a )/i, '')).slice(0, 80);
    } else if (a) {
      const mv = normMovil(j.respuesta);
      if (mv) { a.movil = mv; a.persona_ok = true; a.sin_movil = false; }
      else { a.sin_movil = true; a.persona_ok = true; }
    }
  }
  if (j.eleccion) {
    const { op, i, k } = j.eleccion;
    const a = acciones[i];
    if (a && op === 'q') acciones.splice(i, 1);
    else if (a && op === 'e' && a.pregunta && a.pregunta.opciones && a.pregunta.opciones[k]) {
      const v = a.pregunta.opciones[k].v;
      if (a.pregunta.tipo === 'hora') {
        const t = dt(cfg, v);
        a.fecha = t.toISODate(); a.hora = fHora(t);
      } else if (a.pregunta.tipo === 'persona') {
        if (v === 'otra') { a.persona_otra = true; }
        else { const c = (a.candidatos || [])[Number(v)]; if (c) { a.nombre = c.nombre; a.movil = c.movil; a.persona_ok = true; } }
      } else if (a.pregunta.tipo === 'cual') {
        a.ev_id = v;
      } else if (a.pregunta.tipo === 'movil' && v === 'sin') {
        a.sin_movil = true; a.persona_ok = true;
      }
    }
  }
} else {
  for (const a of j.acciones || []) {
    if (ESCRITURA.includes(a.accion)) {
      acciones.push({ accion: a.accion, nombre: a.nombre, movil: normMovil(a.movil), codigo: a.tipo_cita ? tipoPor(cfg, a.tipo_cita).codigo : null,
        fecha: a.fecha, hora: a.hora, ref_fecha: a.ref_fecha, ref_hora: a.ref_hora, persona_ok: !!normMovil(a.movil) });
      continue;
    }
    // Acciones informativas: se responden ya
    if (a.accion === 'consultar') {
      info.push(textoConsulta(cfg, eventos, a, j.espera || []));
      logs.push(log(cfg, 'bot_agenda', 'consultar', 'ok', `${origen}:c${info.length}`, { canal: m.via_voz ? 'voz' : 'texto' }));
    } else if (a.accion === 'ayuda') {
      info.push(TEXTO_AYUDA[a.tema] || TEXTO_AYUDA.general);
    } else if (a.accion === 'demasiadas') {
      info.push('✋ Solo puedo hacer 5 cosas por mensaje. Mándame el resto en otro.');
    } else if (a.accion === 'error_ia') {
      info.push('😵 Ahora mismo no consigo entender mensajes. Puedes usar /hoy, /huecos o la app, y lo intento de nuevo en un rato.');
      logs.push(log(cfg, 'bot_agenda', 'interpretar', 'error', origen, { motivo: 'api_ia' }));
      admin.push(`⚠️ ${cfg.cliente}: la IA ha fallado (${String(j.ia_error_api || '').slice(0, 150)})`);
    } else if (a.accion === 'saludo') {
      info.push(['👋 ¡Aquí estoy! Dime qué necesitas de tu agenda.', '😊 ¡A mandar! Si necesitas algo de la agenda, dímelo como te salga.'][String(m.upd).length % 2]);
    } else {
      info.push('🙈 Perdona, no lo he pillado. ¿Quieres apuntar, mover o cancelar una cita, o mirar la agenda? Dímelo como te salga.');
      logs.push(log(cfg, 'bot_agenda', 'no_entendido', 'omitido', origen, { canal: m.via_voz ? 'voz' : 'texto' }));
    }
  }
}

// --- 2. Resolver cada acción contra el calendario (con una copia "virtual") ---
let virtual = eventos.filter((e) => e.status !== 'cancelled').map((e) => e);
const quitarVirtual = (id) => { virtual = virtual.filter((e) => e.id !== id); };
const ponerVirtual = (id, ini, fin) => { virtual.push({ id, summary: 'reservado', start: { dateTime: ini.toISO() }, end: { dateTime: fin.toISO() } }); };
const citas = citasDe(cfg, eventos);
const habit = habituales(cfg, eventos);
const hoy0 = ahora(cfg).startOf('day');
const cuando = (t) => `${diaRelativo(cfg, t)} a las ${fHora(t)}`;
const opcionesHora = (lista) => lista.map((t) => ({ t: `${capital(diaRelativo(cfg, t).replace(/^el /, ''))} ${fHora(t)}`, v: t.toISO() }));
const MOTIVO = {
  ocupado: 'está ocupado', horario: 'está fuera de tu horario', cerrado: 'ese día está cerrado', pasado: 'ya ha pasado', fecha: 'no es una fecha válida',
};

const buscarCita = (a) => {
  if (a.ev_id) return { una: citas.find((c) => c.id === a.ev_id) || null, varias: [] };
  let l = citas.filter((c) => (a.nombre ? coincideNombre(c.nombre, a.nombre) : true) && c.inicio >= hoy0);
  if (!a.nombre && !a.ref_fecha && !a.ref_hora) return { una: null, varias: [] };
  if (a.ref_fecha) l = l.filter((c) => c.inicio.toISODate() === a.ref_fecha);
  if (a.ref_hora) l = l.filter((c) => fHora(c.inicio) === a.ref_hora);
  return l.length === 1 ? { una: l[0], varias: [] } : { una: null, varias: l };
};

for (let i = 0; i < acciones.length; i++) {
  const a = acciones[i];
  a.pregunta = null;
  a.estado = 'listo';
  a.motivo = null;

  if (a.accion === 'crear') {
    a.codigo = tipoPor(cfg, a.codigo || 'OTRO').codigo;
    const dur = Number(tipoPor(cfg, a.codigo).min) || 30;
    if (!a.nombre) {
      a.estado = 'pregunta';
      a.pregunta = { tipo: 'nombre', texto: '¿Para quién es la cita? Escríbeme su nombre.', opciones: [] };
    }
    // ¿Quién es? (móvil y nombre canónico a partir de citas anteriores)
    if (!a.pregunta && !a.persona_ok && !a.movil && !a.sin_movil) {
      const cands = [];
      if (!a.persona_otra) {
        for (const h of habit) {
          if (h.movil && coincideNombre(h.nombre, a.nombre) && !cands.some((c) => c.movil === h.movil)) cands.push({ nombre: h.nombre, movil: h.movil });
        }
      }
      if (cands.length === 1) { a.nombre = cands[0].nombre; a.movil = cands[0].movil; a.persona_ok = true; }
      else if (cands.length > 1) {
        a.candidatos = cands.slice(0, 4);
        a.estado = 'pregunta';
        a.pregunta = { tipo: 'persona', texto: `Tengo varias personas llamadas «${esc(a.nombre)}». ¿Cuál es?`,
          opciones: [...a.candidatos.map((c, k) => ({ t: `${c.nombre} · ···${c.movil.slice(-3)}`, v: String(k) })), { t: 'Otra persona', v: 'otra' }] };
      } else {
        a.estado = 'pregunta';
        a.pregunta = { tipo: 'movil', texto: `¿Qué móvil tiene <b>${esc(a.nombre)}</b>? Escríbemelo, o pulsa «Sin móvil» (entonces no le llegarán recordatorios).`,
          opciones: [{ t: 'Sin móvil', v: 'sin' }] };
      }
    }
    // ¿Cuándo?
    if (!a.pregunta) {
      if (!a.fecha && a.hora) {
        const hoyH = dt(cfg, `${ahora(cfg).toISODate()}T${a.hora}`);
        a.fecha = hoyH > ahora(cfg) ? hoyH.toISODate() : ahora(cfg).plus({ days: 1 }).toISODate();
      }
      if (!a.fecha || !a.hora) {
        const base = a.fecha ? dt(cfg, a.fecha).startOf('day') : ahora(cfg);
        const ops = a.fecha ? huecos(cfg, virtual, base, base.endOf('day'), dur).filter((t, k, arr) => k === 0 || t.diff(arr[0], 'minutes').minutes % 60 === 0).slice(0, 4)
          : alternativas(cfg, virtual, base, dur, 4);
        a.estado = 'pregunta';
        a.pregunta = ops.length
          ? { tipo: 'hora', texto: `¿A qué hora apunto a <b>${esc(a.nombre)}</b>${a.fecha ? ' ' + diaRelativo(cfg, base) : ''}? Elige un hueco o dímelo.`, opciones: opcionesHora(ops) }
          : { tipo: 'hora', texto: `No veo huecos libres${a.fecha ? ' ' + diaRelativo(cfg, base) : ''} para <b>${esc(a.nombre)}</b>. Dime otro día.`, opciones: [] };
      }
    }
    if (!a.pregunta) {
      const ini = dt(cfg, `${a.fecha}T${a.hora}`);
      const fin = ini.plus({ minutes: dur });
      const h = comprobarHueco(cfg, virtual, ini, fin);
      if (!h.libre) {
        const ops = alternativas(cfg, virtual, ini.isValid ? ini : ahora(cfg), dur, 3);
        a.estado = 'pregunta';
        a.pregunta = { tipo: 'hora', texto: `Para <b>${esc(a.nombre)}</b>, ${ini.isValid ? cuando(ini) : 'esa hora'} ${MOTIVO[h.motivo]}. ${ops.length ? 'Te propongo:' : 'No encuentro huecos cerca; dime otro día.'}`, opciones: opcionesHora(ops) };
      } else {
        a.inicio = ini.toISO(); a.fin = fin.toISO();
        ponerVirtual(`nuevo${i}`, ini, fin);
      }
    }
  }

  if (a.accion === 'mover' || a.accion === 'cancelar') {
    const { una, varias } = buscarCita(a);
    if (!una && varias.length > 1) {
      a.estado = 'pregunta';
      a.pregunta = { tipo: 'cual', texto: `Hay varias citas${a.nombre ? ' de «' + esc(a.nombre) + '»' : ' que encajan'}. ¿Cuál quieres ${a.accion === 'mover' ? 'mover' : 'cancelar'}?`,
        opciones: varias.slice(0, 4).map((c) => ({ t: `${c.nombre} · ${capital(diaRelativo(cfg, c.inicio).replace(/^el /, ''))} ${fHora(c.inicio)}`, v: c.id })) };
    } else if (!una) {
      a.estado = 'imposible';
      a.motivo = !a.nombre && !a.ref_fecha && !a.ref_hora
        ? `¿Qué cita quieres ${a.accion === 'mover' ? 'mover' : 'cancelar'}? Dime de quién es o cuándo.`
        : `No encuentro ninguna cita${a.nombre ? ' de <b>' + esc(a.nombre) + '</b>' : ''}${a.ref_fecha ? ' ' + diaRelativo(cfg, dt(cfg, a.ref_fecha)) : ''}${a.ref_hora ? ' a las ' + a.ref_hora : ''}.`;
    } else {
      a.ev_id = una.id;
      a.nombre = una.nombre;
      a.movil = una.movil;
      a.codigo = una.codigo;
      a.ini_original = una.inicio.toISO();
      a.fin_original = una.fin.toISO();
      if (a.accion === 'cancelar') {
        quitarVirtual(una.id);
      } else {
        const dur = Math.max(5, Math.round(una.fin.diff(una.inicio, 'minutes').minutes));
        if (!a.fecha && !a.hora) {
          const ops = alternativas(cfg, virtual, una.inicio, dur, 4, una.id);
          a.estado = 'pregunta';
          a.pregunta = { tipo: 'hora', texto: `¿A cuándo muevo a <b>${esc(una.nombre)}</b> (ahora ${cuando(una.inicio)})?`, opciones: opcionesHora(ops) };
        } else {
          const ini = dt(cfg, `${a.fecha || una.inicio.toISODate()}T${a.hora || fHora(una.inicio)}`);
          const fin = ini.plus({ minutes: dur });
          const h = comprobarHueco(cfg, virtual, ini, fin, una.id);
          if (!h.libre) {
            const ops = alternativas(cfg, virtual, ini.isValid ? ini : una.inicio, dur, 3, una.id);
            a.estado = 'pregunta';
            a.pregunta = { tipo: 'hora', texto: `Para mover a <b>${esc(una.nombre)}</b>, ${ini.isValid ? cuando(ini) : 'esa hora'} ${MOTIVO[h.motivo]}. ${ops.length ? 'Te propongo:' : 'Dime otro día.'}`, opciones: opcionesHora(ops) };
          } else {
            a.inicio = ini.toISO(); a.fin = fin.toISO();
            quitarVirtual(una.id);
            ponerVirtual(`mov${i}`, ini, fin);
          }
        }
      }
    }
  }
}

// Las imposibles se explican y se quitan
for (const a of acciones.filter((x) => x.estado === 'imposible')) info.push('⚠️ ' + a.motivo);
acciones = acciones.filter((x) => x.estado !== 'imposible');

// --- 3. Vista ---
const linea = (a) => {
  if (a.accion === 'crear') {
    const t = a.inicio ? cuando(dt(cfg, a.inicio)) : (a.fecha ? diaRelativo(cfg, dt(cfg, a.fecha)) : '¿cuándo?');
    return `➕ Apuntar a <b>${esc(a.nombre || '¿quién?')}</b> · ${t} · ${esc(tipoPor(cfg, a.codigo).nombre)} · ${a.movil ? movilVisible(a.movil) : (a.sin_movil ? 'sin móvil' : '¿móvil?')}`;
  }
  if (a.accion === 'mover') {
    const o = a.ini_original ? cuando(dt(cfg, a.ini_original)) : '?';
    return `🔁 Mover a <b>${esc(a.nombre)}</b> · ${o} → ${a.inicio ? cuando(dt(cfg, a.inicio)) : '¿cuándo?'}`;
  }
  return `🗑 Cancelar a <b>${esc(a.nombre)}</b> · ${a.ini_original ? cuando(dt(cfg, a.ini_original)) : '?'}`;
};
const primeraPregunta = acciones.findIndex((a) => a.estado === 'pregunta');
const partes = [];
if (m.transcripcion) partes.push(`🎧 <i>«${esc(m.transcripcion)}»</i>`);
if (info.length) partes.push(info.join('\n\n'));
let botones = [];
if (acciones.length) {
  partes.push((primeraPregunta >= 0 ? '📝 <b>Esto es lo que voy a hacer:</b>\n' : '📝 <b>¿Lo hago?</b>\n') + acciones.map((a) => (a.estado === 'pregunta' ? '❓ ' : '') + linea(a)).join('\n'));
  if (primeraPregunta >= 0) {
    const a = acciones[primeraPregunta];
    partes.push('❓ ' + a.pregunta.texto);
    botones = a.pregunta.opciones.map((o, k) => [{ text: o.t.slice(0, 60), callback_data: `b|{ID}|e|${primeraPregunta}|${k}` }]);
    botones.push([{ text: '🚫 Quitar esta', callback_data: `b|{ID}|q|${primeraPregunta}` }, { text: '❌ Cancelar todo', callback_data: 'b|{ID}|no' }]);
  } else {
    botones = [[{ text: '✅ Sí, hazlo', callback_data: 'b|{ID}|si' }, { text: '❌ No', callback_data: 'b|{ID}|no' }]];
  }
} else if (j.pendiente) {
  partes.push('👌 No queda nada por hacer.');
}
const texto = partes.join('\n\n').slice(0, 4000) || '🤔 No te he entendido. ¿Qué quieres hacer?';

const base = { m, cfg, consumo: j.consumo || null, logs, admin };
if (!acciones.length) {
  const tg = [];
  if (m.tipo === 'callback') { tg.push(tgAviso(m.cb_id)); tg.push(tgEditar(m.chat_id, m.msg_id, texto, [])); }
  else tg.push(tgTexto(m.chat_id, texto));
  return [{ json: { ...base, guardar: j.pendiente ? { id: j.pendiente.id, acciones: [], estado: 'cancelado', pregunta: null } : null, vista: null, salida_directa: { tg } } }];
}
const pq = primeraPregunta >= 0 ? { i: primeraPregunta, tipo: acciones[primeraPregunta].pregunta.tipo } : null;
return [{ json: { ...base,
  guardar: { id: j.pendiente ? j.pendiente.id : null, acciones, estado: pq && ['movil', 'nombre'].includes(pq.tipo) ? 'esperando_dato' : 'pendiente', pregunta: pq },
  vista: { texto, botones },
} }];

// ---- RESPIRO · utilidades comunes (generadas por n8n/build.py: no editar en n8n) ----
// Fechas con Luxon (DateTime está disponible en los nodos Code de n8n).
const G = $('G').first().json;
const SEP = '·';
const IGNORAR = ['BLOQUEO', 'COMIDA', 'REUNION', 'FORMACION', 'VACACIONES'];
const CERRADO = 'CERRADO';
const NOVINO = 'NOVINO';
const PASO_MIN = 15;          // los huecos se buscan cada 15 min
const AVISO_MIN_MIN = 0;      // el dueño puede apuntar citas para dentro de un rato

const norm = (s) => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase().trim();
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const capital = (s) => String(s || '').replace(/(^|\s)(\p{L})/gu, (m, a, b) => a + b.toUpperCase());

const zona = (cfg) => (cfg && cfg.zona_horaria) || 'Europe/Madrid';
const ahora = (cfg) => DateTime.now().setZone(zona(cfg)).setLocale('es');
const dt = (cfg, v) => DateTime.fromISO(String(v), { zone: zona(cfg) }).setLocale('es');
const fDia = (d) => d.setLocale('es').toFormat("cccc d 'de' LLLL");
const fDiaCorto = (d) => d.setLocale('es').toFormat('ccc d');
const fHora = (d) => d.toFormat('HH:mm');
const diaRelativo = (cfg, d) => {
  const h = ahora(cfg).startOf('day');
  const x = d.setZone(zona(cfg)).startOf('day');
  const n = Math.round(x.diff(h, 'days').days);
  if (n === 0) return 'hoy';
  if (n === 1) return 'mañana';
  if (n === -1) return 'ayer';
  if (n > 1 && n < 7) return 'el ' + x.setLocale('es').toFormat('cccc d');
  return 'el ' + x.setLocale('es').toFormat("cccc d 'de' LLLL");
};

// --- Tipos genéricos de cita (nunca el tratamiento concreto) ---
const tipos = (cfg) => (Array.isArray(cfg.tipos_cita) && cfg.tipos_cita.length ? cfg.tipos_cita
  : [{ codigo: 'OTRO', nombre: 'otro', min: 30 }]);
const tipoPor = (cfg, codigo) => {
  const t = tipos(cfg);
  return t.find((x) => norm(x.codigo) === norm(codigo)) || t.find((x) => x.codigo === 'OTRO') || t[t.length - 1];
};

// --- Teléfonos ---
const normMovil = (p) => {
  if (p === null || p === undefined || p === '') return null;
  let d = String(p).replace(/[^\d+]/g, '');
  if (d.startsWith('+')) d = d.slice(1); else if (d.startsWith('00')) d = d.slice(2);
  if (d.length === 9) d = '34' + d;
  return /^\d{10,15}$/.test(d) ? d : null;
};
const movilVisible = (m) => (m ? '+' + m : 'sin móvil');

// --- Títulos del calendario: "Nombre · +34600111222 · TIPO" ---
const titulo = (cfg, nombre, movil, codigo) =>
  `${capital(nombre).trim()} ${SEP} ${movil ? '+' + movil : 'sin móvil'} ${SEP} ${tipoPor(cfg, codigo).codigo}`;

const leerTitulo = (cfg, summary) => {
  const s = String(summary || '');
  const partes = s.split(SEP).map((x) => x.trim()).filter(Boolean);
  const N = norm(s);
  const novino = N.includes(NOVINO);
  const nombre = (partes[0] || '').replace(new RegExp(NOVINO, 'i'), '').trim();
  let movil = null;
  let codigo = null;
  for (const p of partes.slice(1)) {
    const m = normMovil(p);
    if (!movil && m && /\d{6,}/.test(p.replace(/\s/g, ''))) { movil = m; continue; }
    const t = tipos(cfg).find((x) => norm(p).includes(norm(x.codigo)));
    if (!codigo && t) codigo = t.codigo;
  }
  return { nombre, movil, codigo: codigo || 'OTRO', novino };
};

const esIgnorable = (summary) => IGNORAR.some((p) => norm(summary).startsWith(p));

// Citas (eventos con hora) a partir de la respuesta de Google Calendar
const citasDe = (cfg, eventos) => (eventos || [])
  .filter((e) => e.status !== 'cancelled' && e.start && e.start.dateTime && !esIgnorable(e.summary) && !norm(e.summary).includes(CERRADO))
  .map((e) => {
    const t = leerTitulo(cfg, e.summary);
    return {
      id: e.id,
      inicio: DateTime.fromISO(e.start.dateTime).setZone(zona(cfg)),
      fin: DateTime.fromISO(e.end.dateTime).setZone(zona(cfg)),
      ...t,
    };
  })
  .sort((a, b) => a.inicio.toMillis() - b.inicio.toMillis());

// Ocupación: eventos que bloquean (cualquier evento con hora no transparente
// y los días completos marcados como CERRADO).
const ocupacion = (cfg, eventos, excluirId) => {
  const cerrados = new Set();
  const ocupado = [];
  for (const e of eventos || []) {
    if (e.status === 'cancelled' || e.transparency === 'transparent' || e.id === excluirId) continue;
    if (e.start && e.start.date) {
      if (norm(e.summary).includes(CERRADO)) {
        let d = DateTime.fromISO(e.start.date, { zone: zona(cfg) });
        const fin = DateTime.fromISO(e.end.date, { zone: zona(cfg) });
        while (d < fin) { cerrados.add(d.toISODate()); d = d.plus({ days: 1 }); }
      }
      continue;
    }
    if (!e.start || !e.start.dateTime) continue;
    ocupado.push({ s: DateTime.fromISO(e.start.dateTime).toMillis(), e: DateTime.fromISO(e.end.dateTime).toMillis() });
  }
  return { cerrados, ocupado };
};

const tramosDia = (cfg, d) => ((cfg.horario || {})[String(d.weekday)] || []);

const dentroHorario = (cfg, ini, fin) => tramosDia(cfg, ini).some(([a, b]) =>
  ini.toFormat('HH:mm') >= a && fin.toFormat('HH:mm') <= b && ini.toISODate() === fin.minus({ minutes: 1 }).toISODate());

// ¿Está libre [ini, fin)? Devuelve { libre, motivo }
const comprobarHueco = (cfg, eventos, ini, fin, excluirId) => {
  const { cerrados, ocupado } = ocupacion(cfg, eventos, excluirId);
  if (!ini.isValid) return { libre: false, motivo: 'fecha' };
  if (ini < ahora(cfg).minus({ minutes: 5 })) return { libre: false, motivo: 'pasado' };
  if (cerrados.has(ini.toISODate())) return { libre: false, motivo: 'cerrado' };
  if (!dentroHorario(cfg, ini, fin)) return { libre: false, motivo: 'horario' };
  const s = ini.toMillis();
  const e = fin.toMillis();
  if (ocupado.some((x) => x.s < e && x.e > s)) return { libre: false, motivo: 'ocupado' };
  return { libre: true, motivo: null };
};

// Huecos libres de `dur` minutos entre desde y hasta.
const huecos = (cfg, eventos, desde, hasta, dur, opts = {}) => {
  const { cerrados, ocupado } = ocupacion(cfg, eventos, opts.excluirId);
  const minimo = ahora(cfg).plus({ minutes: AVISO_MIN_MIN });
  const res = [];
  for (let dia = desde.startOf('day'); dia <= hasta; dia = dia.plus({ days: 1 })) {
    if (cerrados.has(dia.toISODate())) continue;
    for (const [a, b] of tramosDia(cfg, dia)) {
      const [ah, am] = a.split(':').map(Number);
      const [bh, bm] = b.split(':').map(Number);
      const cierre = dia.set({ hour: bh, minute: bm, second: 0, millisecond: 0 });
      for (let t = dia.set({ hour: ah, minute: am, second: 0, millisecond: 0 }); t.plus({ minutes: dur }) <= cierre; t = t.plus({ minutes: PASO_MIN })) {
        if (t < minimo || t < desde || t > hasta) continue;
        if (opts.franja === 'manana' && t.hour >= 14) continue;
        if (opts.franja === 'tarde' && t.hour < 14) continue;
        const s = t.toMillis();
        const e = t.plus({ minutes: dur }).toMillis();
        if (!ocupado.some((x) => x.s < e && x.e > s)) res.push(t);
      }
    }
  }
  return res;
};

// Agrupa huecos consecutivos en tramos "10:00–12:30" para mostrarlos.
const tramosLibres = (lista, dur) => {
  const out = [];
  for (const t of lista) {
    const ult = out[out.length - 1];
    if (ult && ult.dia === t.toISODate() && t <= ult.fin) ult.fin = t.plus({ minutes: dur });
    else out.push({ dia: t.toISODate(), ini: t, fin: t.plus({ minutes: dur }) });
  }
  return out;
};

// Siguientes huecos cerca de una hora pedida (mismo día primero, luego días siguientes)
const alternativas = (cfg, eventos, ini, dur, n = 3, excluirId) => {
  const mismoDia = huecos(cfg, eventos, ini.startOf('day'), ini.endOf('day'), dur, { excluirId })
    .sort((a, b) => Math.abs(a.diff(ini).toMillis()) - Math.abs(b.diff(ini).toMillis()));
  const out = [];
  for (const t of mismoDia) {
    if (out.length >= n) break;
    if (out.some((o) => Math.abs(o.diff(t, 'minutes').minutes) < dur)) continue;
    out.push(t);
  }
  if (out.length < n) {
    const otros = huecos(cfg, eventos, ini.plus({ days: 1 }).startOf('day'), ini.plus({ days: 14 }).endOf('day'), dur, { excluirId });
    for (const t of otros) {
      if (out.length >= n) break;
      if (out.some((o) => o.toISODate() === t.toISODate())) continue;   // uno por día
      out.push(t);
    }
  }
  return out.sort((a, b) => a.toMillis() - b.toMillis());
};

// Busca citas por nombre (tolerante a tildes y a nombre parcial).
const coincideNombre = (nombreCita, buscado) => {
  if (!buscado) return false;
  const a = norm(nombreCita);
  const b = norm(buscado);
  if (!a || !b) return false;
  if (a === b) return true;
  const pa = a.split(/\s+/);
  const pb = b.split(/\s+/);
  return pb.every((x) => pa.some((y) => y === x || (x.length >= 4 && y.startsWith(x))));
};

// Pacientes habituales (solo nombre y móvil) sacados del calendario.
const habituales = (cfg, eventos) => {
  const m = new Map();
  for (const c of citasDe(cfg, eventos)) {
    if (!c.nombre) continue;
    const k = norm(c.nombre) + '|' + (c.movil || '');
    const prev = m.get(k);
    if (!prev || prev.ultima < c.inicio) m.set(k, { nombre: c.nombre, movil: c.movil, ultima: c.inicio });
  }
  return [...m.values()].sort((a, b) => b.ultima.toMillis() - a.ultima.toMillis());
};

// Mensaje de Telegram (sendMessage / editMessageText / answerCallbackQuery / sendPhoto)
const tgTexto = (chat_id, text, botones, extra = {}) => ({
  method: 'sendMessage',
  body: {
    chat_id, text, parse_mode: 'HTML', disable_web_page_preview: true,
    ...(botones && botones.length ? { reply_markup: { inline_keyboard: botones } } : {}),
